const LIMITS = { depth: 12, array: 200, nodes: 20000 }; let nodes = 0;
const plain = (v, depth, stack) => { if (v === null || v === undefined) return null; const t = typeof v;
  if (t === 'string' || t === 'boolean') return v; if (t === 'number') return Number.isFinite(v) ? v : String(v);
  if (t === 'bigint' || t === 'symbol') return v.toString(); if (t === 'function') return '[Function ' + (v.name || 'anonymous') + ']';
  if (depth > LIMITS.depth) return '[max depth]'; if (++nodes > LIMITS.nodes) return '[truncated]'; if (stack.includes(v)) return '[circular]';
  if (v instanceof Date) return v.toISOString(); if (v instanceof Error) return { error: v.message, ...(v.code ? { code: v.code } : {}) };
  if (v.documentName && v._id !== undefined) return { _document: v.documentName, _id: v._id, name: v.name ?? null, ...(v.uuid ? { uuid: v.uuid } : {}) };
  const inner = stack.concat([v]); const list = (items, size) => { const out = []; for (const x of items) { if (out.length >= LIMITS.array) { out.push('[+' + (size - LIMITS.array) + ' more]'); break; } out.push(plain(x, depth + 1, inner)); } return out; };
  if (Array.isArray(v)) return list(v, v.length);
  if (v instanceof Map || v instanceof Set || (typeof v.entries === 'function' && typeof v.size === 'number')) return list(v.values(), v.size);
  const out = {}; for (const k of Object.keys(v)) { if (k.startsWith('_') && k !== '_id') continue; let x; try { x = v[k]; } catch { out[k] = '[unserializable]'; continue; } if (x === undefined) continue; out[k] = plain(x, depth + 1, inner); } return out; };
const H = s => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16); };
const res = {};
const run = async (label, f, full) => { nodes = 1; try { const r = await f(); const s = JSON.stringify(plain(r, 1, [])); res[label] = (full && s.length <= 2500) ? s : { len: s.length, h: H(s) }; } catch (e) { res[label] = { threw: e.code || null, msg: e.message }; } };
