const L = CONST.DOCUMENT_OWNERSHIP_LEVELS, out = [];
for (const s of game.scenes) for (const t of s.tokens) {
  const a = t.actor, f = t.flags?.["pentaryn-dropbin"] ?? {}, o = t.delta?.ownership;
  if (a?.type !== "npc" || f.corpse || game.itempiles?.API?.isValidItemPile?.(t)) continue;
  if ((o?.default ?? 0) >= L.LIMITED) out.push({ scene: s.name, sceneId: s.id, token: t.name, tokenId: t.id,
    linked: t.actorLink, disposition: t.disposition, ownership: o, dropbinFlags: f });
}
return JSON.stringify(out);

const mk = async (name) => Scene.create({ name, width: 2000, height: 1500, padding: 0, grid: { size: 100 }, tokenVision: false, fog: { exploration: false } });
const A = await mk("ZZ Arena A"); const B = await mk("ZZ Arena B");
const u = await User.create({ name: "ZZ Tester", role: CONST.USER_ROLES.PLAYER });
const g = await Actor.create({ name: "ZZ Goblin", type: "npc", system: { attributes: { hp: { value: 7, max: 7 } } }, prototypeToken: { actorLink: false, disposition: -1, sight: { enabled: true } } });
await g.createEmbeddedDocuments("Item", [{ name: "ZZ Rusty Dagger", type: "weapon", system: { quantity: 1 } }]);
const [t1] = await A.createEmbeddedDocuments("Token", [{ ...(await g.getTokenDocument({ x: 500, y: 500 })).toObject() }]);
const [t2] = await A.createEmbeddedDocuments("Token", [{ ...(await g.getTokenDocument({ x: 800, y: 500 })).toObject() }]);
return { A: A.id, B: B.id, user: u.id, goblin: g.id, t1: { id: t1.id, link: t1.actorLink, disp: t1.disposition, own: t1.delta?.ownership ?? null, sight: t1.sight.enabled }, t2: t2.id };

