const log = []; const t0 = performance.now();
const h = Hooks.on("updateToken", (doc, ch) => { if (doc.id === t.id) log.push({ ms: Math.round(performance.now() - t0), keys: Object.keys(foundry.utils.flattenObject(ch)).filter(k => !k.startsWith("_stats")).slice(0, 12), own: foundry.utils.getProperty(ch, "delta.ownership") }); });
try {
