  for (let i = 0; i < 50 && t.flags?.["pentaryn-dropbin"]?.corpse; i++) await wait(100);
  await wait(1500);
  return { dead, revived: { own: t.delta?._source?.ownership ?? null, flags: t.flags?.["pentaryn-dropbin"], dead: t.actor.statuses.has("dead"), pile: game.itempiles.API.isValidItemPile(t) }, log };
} finally { Hooks.off("updateToken", h); }

