    return r;
  });
  D.toasts = takeToasts();

  out.timings.computeSlots = await timeIt(() => A.computeSlots(owner), 9, 200);
  out.timings.away = await timeIt(() => A.away(owner), 9, 500);
  const quiet = console.table, quietLog = console.log;
