const P = foundry.canvas.layers.ControlsLayer.prototype;
const route = foundry.utils.getRoute('modules/pentaryn-pings/pings.mjs');
const out = { now: new Date().toISOString() };
const ns = () => game.pentaryn.pings;
const view = () => ({ patches: ns().describe().patches.map(p => p.marker + '|' + p.label), marked: !!P.handlePing.__pentarynPatched });
out.before = view();
const ours0 = P.handlePing;
// Phase A: plain uninstall + hot re-install
ns().uninstall();
out.afterUninstall = { patches: ns().describe().patches.length, marked: !!P.handlePing.__pentarynPatched };
const core = P.handlePing;
await import(`${route}?kitR1a=${Date.now()}`);
const oursA = P.handlePing;
out.afterReinstallA = { ...view(), wrapsCore: oursA !== core, sameAsBefore: oursA === ours0 };
// Phase B: foreign wrapper on top of ours, then uninstall + re-install
const foreign = function (...a) { return oursA.apply(this, a); };
P.handlePing = foreign;
ns().uninstall();
out.afterUninstallB = { patches: ns().describe().patches.length, topIsForeign: P.handlePing === foreign };
await import(`${route}?kitR1b=${Date.now()}`);
out.afterReinstallB = { ...view(), topIsForeign: P.handlePing === foreign, foreignWrapsOursA: true };
// restore: drop the foreign wrapper so our single wrapper sits directly on core
P.handlePing = oursA;
out.restored = { ...view(), topIsOurs: P.handlePing === oursA, oursMarked: !!oursA.__pentarynPatched };
return out;

