window.__zzImp = async (opts) => {
  const lines = [], toasts = [];
  const orig = { warn: console.warn, error: console.error, info: console.info, log: console.log, table: console.table };
  const n = ui.notifications; const on = n.notify;
  const fmt = a => a.map(x => typeof x === 'string' ? x : (x?.message ?? (()=>{try{return JSON.stringify(x)}catch{return String(x)}})())).join(' ');
  for (const k of Object.keys(orig)) console[k] = (...a) => { lines.push(k + ': ' + fmt(a).slice(0, 300)); return orig[k].apply(console, a); };
  n.notify = function (msg, type, o) { toasts.push({ type, msg: String(msg).slice(0, 300), permanent: !!o?.permanent }); return on.call(this, msg, type, o); };
  const before = game.actors.filter(a => a.name.startsWith('ZZ')).map(a => a.id);
  let result, error;
  try { result = await game.pentaryn.import(opts); }
  catch (e) { error = { name: e.name, code: e.code, message: String(e.message).slice(0, 400) }; }
  finally { Object.assign(console, orig); n.notify = on; }
  const after = game.actors.filter(a => a.name.startsWith('ZZ')).map(a => ({ id: a.id, name: a.name, slug: a.flags?.pentaryn?.slug }));
  return { result: result && { ok: result.ok, counts: result.counts, created: result.created, updated: result.updated, skipped: result.skipped, failed: result.failed, deleteJson: result.deleteJson?.required }, error, toasts, lines: lines.filter(l => /pentaryn|failed|FAILED|Import|zz-/i.test(l)).slice(0, 40), zzBefore: before, zzAfter: after };
};
return typeof window.__zzImp;

