const out = { world: game.world.id, dnd5e: game.system.version };
const CUR = ["dnd-players-handbook.spells", "dnd5e.spells24"];
out.packsPresent = Object.fromEntries(["dnd-players-handbook.spells","dnd5e.spells24","dnd5e.spells"].map(id => [id, !!game.packs.get(id)]));
const idx = {};
for (const id of [...CUR, "dnd5e.spells"]) { const p = game.packs.get(id); if (p) idx[id] = await p.getIndex({ fields: ["system.identifier", "system.level"] }); }
const counterparts = (spell) => {
  const res = [];
  for (const id of CUR) {
    const index = idx[id]; if (!index) continue;
    const ident = spell.system?.identifier;
    const w = spell.name.toLowerCase();
    const hit = (ident ? index.find(e => e.system?.identifier === ident) : undefined) ?? index.find(e => e.name.toLowerCase() === w);
    if (hit) res.push({ uuid: `Compendium.${id}.Item.${hit._id}`, name: hit.name, via: (ident && hit.system?.identifier === ident) ? "identifier" : "name" });
  }
  return res;
};
const reg = dnd5e.registry.spellLists;
const wiz = reg.forType("class", "wizard"), cleric = reg.forType("class", "cleric");
out.hasLists = { wizard: !!wiz, cleric: !!cleric, wizardCount: wiz?.uuids?.size };
// sample uuids in wizard registry: which packs?
const packsInList = {}; for (const u of wiz.uuids) { const m = u.match(/^Compendium\.([^.]+\.[^.]+)\./); const k = m?.[1] ?? "other"; packsInList[k] = (packsInList[k] ?? 0) + 1; }
out.wizardListPacks = packsInList;
const fb = idx["dnd5e.spells"].find(e => e.name === "Fireball");
const fb14 = `Compendium.dnd5e.spells.Item.${fb._id}`;
const fbDoc = await fromUuid(fb14);
out.fireball = { u14: fb14, doc_pack: fbDoc.pack, compendiumSource: fbDoc._stats?.compendiumSource ?? null, hasDoc: wiz.has(fbDoc), cps: counterparts(fbDoc).map(c => ({...c, wizardHas: wiz.has(c.uuid), clericHas: cleric.has(c.uuid)})) };
// sweep all 2014 SRD spells
let total=0, onAlready=0, viaCp=0, viaCpIdent=0, viaCpName=0, noCp=0, cpOffList=0; const examples = {name: [], noCp: [], levelMismatch: []};
for (const e of idx["dnd5e.spells"]) {
  total++;
  const doc = await fromUuid(`Compendium.dnd5e.spells.Item.${e._id}`);
  const classes = ["bard","cleric","druid","paladin","ranger","sorcerer","warlock","wizard"];
  const lists = classes.map(c => reg.forType("class", c)).filter(Boolean);
  if (lists.some(l => l.has(doc))) { onAlready++; continue; }
  const cps = counterparts(doc);
  if (!cps.length) { noCp++; if (examples.noCp.length < 12) examples.noCp.push(doc.name); continue; }
  const match = cps.find(c => lists.some(l => l.has(c.uuid)));
  if (match) { viaCp++; if (match.via === "identifier") viaCpIdent++; else { viaCpName++; if (examples.name.length < 8) examples.name.push(`${doc.name} -> ${match.name}`); }
    const cpIdx = idx[match.uuid.split(".").slice(1,3).join(".")]?.get?.(match.uuid.split(".").pop());
    if (cpIdx && cpIdx.system?.level !== e.system?.level && examples.levelMismatch.length < 8) examples.levelMismatch.push(`${doc.name} L${e.system?.level} -> ${match.name} L${cpIdx.system?.level}`);
  } else cpOffList++;
}
out.sweep = { total, onAlready, viaCp, viaCpIdent, viaCpName, noCp, cpOffList, examples };
const melf = idx["dnd5e.spells"].find(e => /acid arrow/i.test(e.name));
out.melf = melf && { name: melf.name, ident: melf.system?.identifier, cps: counterparts(await fromUuid(`Compendium.dnd5e.spells.Item.${melf._id}`)) };
return out;

